<template><section class="build-certificate" aria-label="Watch build certificate"><p>ATELIER TIME</p><h1>ASSEMBLY CERTIFICATE</h1><span class="certificate-rule" /><div class="certificate-build">BUILD / {{ summary.buildNumber }}</div><div class="certificate-model">{{ summary.case?.name }}<br>{{ summary.dial?.name }}</div><p class="certificate-signature">INDIVIDUALLY CONFIGURED · ¥ {{ summary.total.toLocaleString() }}</p><div><button @click="$emit('copy')">SAVE LINK</button><button @click="$emit('edit')">EDIT BUILD</button></div></section></template>
<script setup>defineProps({summary:{type:Object,required:true}}); defineEmits(['copy','edit'])</script>
